def grig(lang):
 s=F.start(150)+t(80,70,'R—MgX  +',16)+t(170,30,'O',14)+line(167,36,167,52)+line(173,36,173,52)+t(170,70,'C',16)+line(167,78,167,94)+line(173,78,173,94)+t(170,110,'O',14)+t(170,130,lb(lang,'carbon dioxide'),12)
